# Marketplace scaffold: auth + listings

Used-gear marketplace. I'll set up:

- **Email + password auth** with a session provider
- **Schema:** `profiles`, `listings`, `listing_images`, `favorites` with RLS
- **Screens:** sign in / sign up, listings feed, listing detail, create listing, my listings
- **Storage** bucket for listing photos

## 1) Supabase schema

Run this in the Supabase SQL editor.

### `supabase/schema.sql`

```sql
-- ============ PROFILES ============
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  username text unique,
  display_name text,
  avatar_url text,
  created_at timestamptz default now()
);

alter table public.profiles enable row level security;

create policy "Profiles are viewable by everyone"
  on public.profiles for select using (true);

create policy "Users can insert their own profile"
  on public.profiles for insert with check (auth.uid() = id);

create policy "Users can update their own profile"
  on public.profiles for update using (auth.uid() = id);

-- Auto-create profile on signup
create function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1)));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ============ LISTINGS ============
create type listing_condition as enum ('new', 'like_new', 'good', 'fair', 'for_parts');
create type listing_status as enum ('active', 'sold', 'paused', 'removed');

create table public.listings (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.profiles(id) on delete cascade,
  title text not null check (char_length(title) between 3 and 120),
  description text,
  category text not null,
  condition listing_condition not null,
  price_cents integer not null check (price_cents >= 0),
  currency text not null default 'USD',
  location text,
  status listing_status not null default 'active',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create index listings_status_created_idx on public.listings (status, created_at desc);
create index listings_seller_idx on public.listings (seller_id);
create index listings_category_idx on public.listings (category);

alter table public.listings enable row level security;

create policy "Active listings are viewable by everyone"
  on public.listings for select using (status = 'active' or seller_id = auth.uid());

create policy "Authenticated users can create listings"
  on public.listings for insert with check (auth.uid() = seller_id);

create policy "Sellers can update their listings"
  on public.listings for update using (auth.uid() = seller_id);

create policy "Sellers can delete their listings"
  on public.listings for delete using (auth.uid() = seller_id);

-- updated_at trigger
create function public.set_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end;
$$;

create trigger listings_updated_at
  before update on public.listings
  for each row execute function public.set_updated_at();

-- ============ LISTING IMAGES ============
create table public.listing_images (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.listings(id) on delete cascade,
  storage_path text not null,
  position smallint not null default 0,
  created_at timestamptz default now()
);

create index listing_images_listing_idx on public.listing_images (listing_id, position);

alter table public.listing_images enable row level security;

create policy "Listing images viewable by everyone"
  on public.listing_images for select using (true);

create policy "Sellers manage their listing images"
  on public.listing_images for all
  using (exists (select 1 from public.listings l where l.id = listing_id and l.seller_id = auth.uid()))
  with check (exists (select 1 from public.listings l where l.id = listing_id and l.seller_id = auth.uid()));

-- ============ FAVORITES ============
create table public.favorites (
  user_id uuid not null references public.profiles(id) on delete cascade,
  listing_id uuid not null references public.listings(id) on delete cascade,
  created_at timestamptz default now(),
  primary key (user_id, listing_id)
);

alter table public.favorites enable row level security;

create policy "Users see their own favorites"
  on public.favorites for select using (auth.uid() = user_id);

create policy "Users add their own favorites"
  on public.favorites for insert with check (auth.uid() = user_id);

create policy "Users remove their own favorites"
  on public.favorites for delete using (auth.uid() = user_id);

-- ============ STORAGE ============
insert into storage.buckets (id, name, public) values ('listing-images', 'listing-images', true)
on conflict (id) do nothing;

create policy "Public read listing images"
  on storage.objects for select using (bucket_id = 'listing-images');

create policy "Authenticated upload listing images"
  on storage.objects for insert
  with check (bucket_id = 'listing-images' and auth.role() = 'authenticated');

create policy "Owners update/delete their listing images"
  on storage.objects for update using (bucket_id = 'listing-images' and owner = auth.uid());

create policy "Owners delete their listing images"
  on storage.objects for delete using (bucket_id = 'listing-images' and owner = auth.uid());
```

